it.each(adjunctCases)("language attribute adjunct: $id", async ({ code }) => {
  await runtime.reset();
  const result = await runtime.evalDetailed(code);
  expect(result.value).toBe(true);
  expect(result.warnings).toEqual([]);
  expect(result.topLevelErrors).toEqual([]);
  expect(result.output).toEqual([]);
});

// NativR-only boundary: general mode-result metadata is not part of the native call matrix.
it("retains the attributed call mode boundary without desynchronizing syntax metadata", async () => {
  await runtime.reset();
  await runtime.eval('owned<-structure(list(quote(identity),17L),note="original");NULL');
  await expect(runtime.eval('mode(owned)<-"call"')).rejects.toMatchObject({ code: "NRU6250" });
  expect(
    await runtime.eval(
      'typeof(owned)=="list"&&identical(attr(owned,"note"),"original")&&sys.nframe()==0L',
    ),
  ).toBe(true);
  expect(await runtime.eval('bare<-list(quote(identity),23L);mode(bare)<-"call";eval(bare)')).toBe(
    23,
  );
});
